<?php
require_once '../includes/auth.php';requireActiveUser();requireTenantContext();requireModulePermission('hotspot','view');global $conn;$tenantId=(int)getCurrentTenantId();$rows=[];if(flexihubTableHasColumn('active_sessions','tenant_id')){$q=$conn->prepare("SELECT * FROM active_sessions WHERE tenant_id=? ORDER BY id DESC LIMIT 200");if($q){$q->bind_param('i',$tenantId);$q->execute();$z=$q->get_result();while($r=$z->fetch_assoc())$rows[]=$r;$q->close();}}$pageTitle='Hotspot Sessions';require_once '../includes/header.php';?><div class="dashboard-card"><h2>Hotspot Sessions</h2><p><?=count($rows)?> session record(s).</p><?php if($rows):?><div class="table-responsive"><table><thead><tr><?php foreach(array_keys($rows[0]) as $k):?><th><?=e(ucwords(str_replace('_',' ',$k)))?></th><?php endforeach;?></tr></thead><tbody><?php foreach($rows as $r):?><tr><?php foreach($r as $v):?><td><?=e($v)?></td><?php endforeach;?></tr><?php endforeach;?></tbody></table></div><?php endif;?></div><?php require_once '../includes/footer.php';?>